SELECT orders.order_status, COUNT(*) AS order_count
FROM orders
GROUP BY orders.order_status;

SELECT 
  EXTRACT(DAY FROM 
    (order_delivered_customer_date - order_purchase_timestamp)
  )::numeric::double precision AS average_delivery_days
FROM 
  orders;

SELECT payment_type, SUM(payment_value) AS total_paid
FROM order_payments
GROUP BY payment_type;

SELECT review_score, COUNT(*) AS count
FROM order_reviews
GROUP BY review_score;

SELECT COUNT(*) 
FROM products 
WHERE product_weight_g > 10000;

SELECT COUNT(*) 
FROM order_reviews 
WHERE review_comment_message IS NOT NULL;

SELECT payment_type, COUNT(*) AS payment_count
FROM order_payments
GROUP BY payment_type;

SELECT product_photos_qty, COUNT(*) AS photo_count
FROM products
GROUP BY product_photos_qty;

SELECT COUNT(DISTINCT order_id) AS total_orders_last_year
FROM orders
WHERE EXTRACT(YEAR FROM order_purchase_timestamp) = EXTRACT(YEAR FROM CURRENT_DATE) - 1;
